import { createTraceContext, useSpeech } from '@pixelkit-labs/sdk';

function TalkBack() {
  const speech = useSpeech();

  const answer = async () => {
    const run = { context: createTraceContext({ runId: `speech-${Date.now()}` }) };
    await speech.speak('The device is ready.', run, { rate: 0.95 });
  };
  return <Button title="Speak" onPress={answer} disabled={speech.isSpeaking} />;
}
